103	+package hotel.documents;
104	+
105	+import hotel.reservations.Guest;
106	+import hotel.reservations.Price;
107	+import hotel.reservations.Reservation;
108	+import hotel.rooms.Room;
109	+import java.math.BigDecimal;
110	+import java.time.LocalDate;
111	+
112	+/**
113	+ * The text of a reservation document. The sequence of lines is the same for every kind of document and is written
114	+ * here once; each kind says only what is its own: the language, the way money and dates are written, who is named
115	+ * and what comes after the total.
116	+ */
117	+abstract class DocumentLayout {
118	+
119	+    abstract String title();
120	+
121	+    /** The word between the title and the reservation number ("nº", "no."). */
122	+    abstract String numberMark();
123	+
124	+    abstract String party(Guest guest);
125	+
126	+    abstract String roomLabel();
127	+
128	+    abstract String checkInLabel();
129	+
130	+    abstract String checkOutLabel();
131	+
132	+    abstract String nights(int count);
133	+
134	+    abstract String subtotalLabel();
135	+
136	+    abstract String discountLabel();
137	+
138	+    abstract String totalLabel();
139	+
140	+    abstract String money(BigDecimal amount);
141	+
142	+    abstract String date(LocalDate date);
143	+
144	+    /** Lines after the total; none by default. */
145	+    String closing(Price price) {
146	+        return "";
147	+    }
148	+
149	+    final String text(Reservation reservation, Room room) {
150	+        Price price = reservation.price();
151	+        StringBuilder text = new StringBuilder();
152	+        text.append(title()).append(' ').append(numberMark()).append(' ').append(reservation.id()).append('\n');
153	+        text.append(party(reservation.guest()));
154	+        text.append(roomLabel()).append(": ").append(room.number()).append(" (").append(room.type()).append(")\n");
155	+        text.append(checkInLabel()).append(": ").append(date(reservation.checkIn()))
156	+                .append(" | ").append(checkOutLabel()).append(": ").append(date(reservation.checkOut()))
157	+                .append(" | ").append(nights(price.nights())).append('\n');
158	+        text.append(subtotalLabel()).append(": ").append(money(price.subtotal())).append('\n');
159	+        if (price.discount().signum() > 0) {
160	+            text.append(discountLabel()).append(": ").append(money(price.discount())).append('\n');
161	+        }
162	+        text.append(totalLabel()).append(": ").append(money(price.total())).append('\n');
163	+        text.append(closing(price));
164	+        return text.toString();
165	+    }
166	+}
