478	+    }
479	+
480	+    /** Exactly one kind may have fields filled in, and it must have all of them. */
481	+    public static Identification of(
482	+            String cpf, String companyCnpj, String companyName, String passport, String country) {
483	+        List<Candidate> candidates = List.of(
484	+                new Candidate(() -> new CpfIdentification(cpf), cpf),
485	+                new Candidate(() -> new CompanyIdentification(companyCnpj, companyName), companyCnpj, companyName),
486	+                new Candidate(() -> new PassportIdentification(passport, country), passport, country));
487	+        List<Candidate> touched = candidates.stream().filter(Candidate::touched).toList();
488	+        if (touched.size() != 1 || !touched.get(0).complete()) {
489	+            throw new HotelException(ErrorCode.INVALID_REQUEST,
490	+                    "identify the guest with exactly one of: guestCpf; companyCnpj and companyName; "
491	+                            + "guestPassport and guestCountry");
492	+        }
493	+        return touched.get(0).kind().get();
494	+    }
495	+
496	+    private record Candidate(Supplier<Identification> kind, String... fields) {
497	+
498	+        boolean touched() {
499	+            return Arrays.stream(fields).anyMatch(field -> !isBlank(field));
500	+        }
501	+
502	+        boolean complete() {
503	+            return Arrays.stream(fields).noneMatch(Identifications::isBlank);
504	+        }
505	+    }
506	+
507	+    private static boolean isBlank(String text) {
508	+        return text == null || text.isBlank();
509	+    }
510	+}
